// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Make caller a program operator
        address caller = address(0x1234);
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.initialize();
        vm.prank(caller);
        c.updateRoundImplementation(payable(address(0x5678)));
        vm.prank(caller);
        c.updateAlloSettings(address(0x9ABC));
        vm.prank(caller);
        c.programOperators(caller, true); // Actually set program operator
        vm.prank(caller);
        c.programOperators(caller, true); // Ensure it's set
        // Now call create to set up something
        bytes memory encodedParams = abi.encode(uint256(1));
        vm.prank(caller);
        c.create(encodedParams, caller);
        // Attempt to transfer ownership to zero address
        bool ok;
        try c.transferOwnership(address(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference (correct) reverts because newOwner == address(0) reverts.
        // Bug (mutant) allows it because require(newOwner == address(0)) passes.
        // So reference: ok == false, bug: ok == true.
        // We assert that the actual behavior is the reference behavior (revert).
        // This passes on reference, fails on bug.
        assertTrue(!ok, "transferOwnership zero should revert");
    }
}

