pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: initialize the contract, become owner, set roundImplementation and alloSettings, add program operator
        vm.startPrank(address(0xAAAA)); // dummy address as owner
        c.initialize();
        c.updateRoundImplementation(payable(address(0xBBBB)));
        c.updateAlloSettings(address(0xCCCC));
        c.programOperators(address(0xDDDD), true);
        vm.stopPrank();

        // Now act as program operator to call create
        bytes memory emptyParams = "";
        address ownedBy = address(0xEEEE);
        vm.prank(address(0xDDDD));
        c.create(emptyParams, ownedBy);

        // Check that after create, the contract's owner (through public getter) is still address(0xAAAA) (reference) vs zero address (bug)
        assertTrue(c.owner() == address(0xAAAA), "Owner should remain original owner after create");
    }
}

